            while (l > 0 && k > 0 && numArray[l - 1] > numArray[r]) {
                l--;
                k--;
            }
            numArray[l++] = numArray[r];
        }

        l -= k;
        int i = 0;
        while (i < l && numArray[i] == '0') {
            i++;
        }
        String res = new String(numArray, i, l - i);
        return res.isEmpty() ? "0" : res;
    }
}
